css:
.email {
  background-color: #222222;
  border-radius: 5px;
  transition: background-color 0.1s cubic-bezier(0.33, 1, 0.68, 1);
}

.email--input {
  width: 200px;
  height: 50px;
  border: 2px solid #222222;
  border-radius: 5px;
  padding: 0 20px;
  color: #222222;
  background-color: #e8e8e8;
  font-size: 15px;
  font-weight: bold;
  font-family: system-ui;
  transition:
    transform 0.1s cubic-bezier(0.33, 1, 0.68, 1),
    border-color 0.1s cubic-bezier(0.33, 1, 0.68, 1);
}

.email--input:focus {
  outline: none;
  transform: translateY(-3px);
}

.email--input::placeholder {
  color: #646464;
  font-size: 15px;
  font-weight: bold;
  font-family: system-ui;
}

.email:has(input:invalid:not(:focus)) {
  background-color: #f25f5c;
}

.email--input:invalid:not(:focus) {
  border: 2px solid #f25f5c;
}

.error {
  font-size: 11px;
  color: #e8e8e8;
  margin-top: 3px;
  user-select: none;
  transition: color 0.1s cubic-bezier(0.33, 1, 0.68, 1);
}

.email:has(input:invalid:not(:focus)) + .error {
  color: #f25f5c;
}
